#include <memory>
#include <string>
#include <iostream>

int main() {
    std::unique_ptr<std::string> p1 = std::make_unique<std::string>("Stegosaurus");  // p1 owns the string
    std::unique_ptr<std::string> p2 = std::move(p1);  // Transfers ownership from p1 to p2
    // Now p1 is empty (nullptr), and p2 owns the string
    if (p2) {
        std::cout << *p2 << std::endl;  // Outputs: Stegosaurus
    }
    // p1 no longer owns the resource, so accessing it would be invalid
    return 0;
}
